alter table public.player_season add column if not exists requested_program text; alter table public.player_season add column if not exists requested_division text; create table if not exists public.portal_pin(auth_user_id uuid not null references auth.users(id) on delete cascade,role text not null,pin_hash text not null,updated_at timestamptz not null default now(),primary key(auth_user_id,role)); alter table public.portal_pin enable row level security; revoke all on public.portal_pin from anon,authenticated; create or replace function public.set_my_portal_pin(p_role text,p_pin text) returns void language plpgsql security definer set search_path=public,extensions as $$begin if auth.uid() is null then raise exception 'Sign in required';end if;if p_pin !~ '^[0-9]{4}$' then raise exception 'PIN must be exactly 4 digits';end if;if not exists(select 1 from public.app_role where auth_user_id=auth.uid() and role=p_role) then raise exception 'Role not authorized';end if;insert into public.portal_pin values(auth.uid(),p_role,crypt(p_pin,gen_salt('bf')),now()) on conflict(auth_user_id,role) do update set pin_hash=excluded.pin_hash,updated_at=now();end$$; create or replace function public.verify_my_portal_pin(p_role text,p_pin text) returns boolean language sql security definer set search_path=public,extensions as $$select exists(select 1 from public.portal_pin pp join public.app_role ar on ar.auth_user_id=pp.auth_user_id and ar.role=pp.role where pp.auth_user_id=auth.uid() and pp.role=p_role and pp.pin_hash=crypt(p_pin,pp.pin_hash))$$; create or replace function public.has_my_portal_pin(p_role text) returns boolean language sql security definer set search_path=public as $$select exists(select 1 from public.portal_pin where auth_user_id=auth.uid() and role=p_role)$$; revoke all on function public.set_my_portal_pin(text,text) from public,anon; revoke all on function public.verify_my_portal_pin(text,text) from public,anon; revoke all on function public.has_my_portal_pin(text) from public,anon; grant execute on function public.set_my_portal_pin(text,text) to authenticated; grant execute on function public.verify_my_portal_pin(text,text) to authenticated; grant execute on function public.has_my_portal_pin(text) to authenticated;